PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX session_user ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX account_user ON account(userId);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER, updatedAt INTEGER);
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE rateLimit (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, lastRequest INTEGER NOT NULL);
CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at INTEGER NOT NULL, resolve_poisoned_results INTEGER NOT NULL DEFAULT 1, daily_run_limit INTEGER NOT NULL DEFAULT 20 CHECK(daily_run_limit BETWEEN 1 AND 100));
CREATE TABLE memberships (org_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','admin','member','viewer')), created_at INTEGER NOT NULL, PRIMARY KEY(org_id,user_id));
CREATE INDEX memberships_user ON memberships(user_id);
CREATE TABLE invites (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('admin','member','viewer')), expires_at INTEGER NOT NULL, created_by TEXT NOT NULL REFERENCES user(id), claimed_by TEXT REFERENCES user(id), created_at INTEGER NOT NULL);
CREATE TABLE brands (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, domain TEXT NOT NULL DEFAULT '', aliases TEXT NOT NULL DEFAULT '[]', kind TEXT NOT NULL CHECK(kind IN ('own','client','competitor')), created_at INTEGER NOT NULL, UNIQUE(org_id,id));
CREATE TABLE workspaces (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, brand_id TEXT, created_at INTEGER NOT NULL, UNIQUE(org_id,id), FOREIGN KEY(org_id,brand_id) REFERENCES brands(org_id,id));
CREATE TABLE prompts (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, workspace_id TEXT NOT NULL, brand_id TEXT, text TEXT NOT NULL, location_name TEXT NOT NULL DEFAULT 'United States', language_code TEXT NOT NULL DEFAULT 'en', engine TEXT NOT NULL DEFAULT 'chatgpt' CHECK(engine IN ('chatgpt','gemini','google')), mode TEXT NOT NULL DEFAULT 'standard' CHECK(mode IN ('standard','priority','live')), enabled INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(org_id,id), FOREIGN KEY(org_id,workspace_id) REFERENCES workspaces(org_id,id) ON DELETE CASCADE, FOREIGN KEY(org_id,brand_id) REFERENCES brands(org_id,id));
CREATE INDEX prompts_workspace ON prompts(org_id,workspace_id);
CREATE TABLE credentials (org_id TEXT PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, ciphertext TEXT NOT NULL, key_version INTEGER NOT NULL DEFAULT 1, updated_at INTEGER NOT NULL);
CREATE TABLE api_keys (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, name TEXT NOT NULL, prefix TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, scopes TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, last_used_at INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE schedules (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, prompt_id TEXT NOT NULL, preset TEXT NOT NULL CHECK(preset IN ('daily','weekly','mwf','custom')), days TEXT NOT NULL, local_time TEXT NOT NULL, timezone TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, last_slot TEXT, created_at INTEGER NOT NULL, UNIQUE(org_id,id), FOREIGN KEY(org_id,prompt_id) REFERENCES prompts(org_id,id) ON DELETE CASCADE);
CREATE TABLE usage_daily (org_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, day TEXT NOT NULL, runs INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(org_id,day));
CREATE TABLE runs (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, prompt_id TEXT NOT NULL, workspace_id TEXT NOT NULL, prompt_text TEXT NOT NULL, config TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','submitting','submitted','succeeded','failed','uncertain')), task_id TEXT, answer_text TEXT, citations TEXT, mentions TEXT, grounding_queries TEXT, organic_results TEXT, discovered_brands TEXT, has_answer INTEGER NOT NULL DEFAULT 0, analysis TEXT, raw_key TEXT, error TEXT, provider_cost REAL NOT NULL DEFAULT 0, idempotency_key TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY(org_id,prompt_id) REFERENCES prompts(org_id,id), FOREIGN KEY(org_id,workspace_id) REFERENCES workspaces(org_id,id), UNIQUE(org_id,idempotency_key));
CREATE INDEX runs_org ON runs(org_id,created_at);
CREATE INDEX runs_status ON runs(status,updated_at);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_id TEXT NOT NULL, action TEXT NOT NULL, resource_id TEXT, created_at INTEGER NOT NULL);
CREATE TABLE request_limits (key TEXT NOT NULL, bucket INTEGER NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(key,bucket));
